const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const fmtTime = seconds => { seconds = Math.max(0, Math.floor(Number(seconds) || 0)); const h=Math.floor(seconds/3600),m=Math.floor(seconds%3600/60); return h ? `${h}h ${m}m` : `${m}m`; };
const dateFmt = value => value ? new Date(value).toLocaleString([], {month:'short', day:'numeric', hour:'2-digit', minute:'2-digit'}) : '';
function toast(message) { const el=$('toast'); el.textContent=message; el.classList.add('show'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>el.classList.remove('show'),3300); }
function message(id, text, good=false) { const el=$(id); if(!el)return; el.textContent=text||''; el.classList.toggle('good', Boolean(good)); }
async function api(path, options={}) {
  const method = String(options.method || 'GET').toUpperCase();
  const cacheable = method === 'GET' && !options.signal;
  const cacheKey = `${token || 'anonymous'}:${path}`;
  const now = Date.now();
  if (method !== 'GET') {
    // Do not let a read started before a write be reused or cached afterward.
    apiCacheGeneration++;
    apiResponseCache.clear();
    apiRequestsInFlight.clear();
  }
  const cacheGenerationAtStart = apiCacheGeneration;
  if (cacheable) {
    const cached = apiResponseCache.get(cacheKey);
    if (cached && cached.expiresAt > now) return cached.data;
    if (apiRequestsInFlight.has(cacheKey)) return apiRequestsInFlight.get(cacheKey);
  }
  const request = (async () => {
    const headers = new Headers(options.headers || {}); headers.set('Accept','application/json');
    if(options.body && !(options.body instanceof FormData)) headers.set('Content-Type','application/json');
    if(token) headers.set('Authorization', `Bearer ${token}`);
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), Number(options.timeoutMs) || 12000);
    let response;
    try {
      response = await fetch(`${API_BASE}${path}`, {...options, headers, signal: options.signal || controller.signal, body: options.body && typeof options.body!=='string' && !(options.body instanceof FormData) ? JSON.stringify(options.body) : options.body});
    } catch (error) {
      if (error?.name === 'AbortError') throw new Error('The request took too long. Check your connection and retry.');
      throw new Error('Cannot connect to Study Lock. Check your connection and try again.');
    } finally { clearTimeout(timeout); }
    const data = await response.json().catch(()=>({}));
    if(!response.ok) { if(response.status===401 && token) { token='';localStorage.removeItem(TOKEN_KEY);showAuth(); } throw new Error(data.error || `Request failed (${response.status}).`); }
    if (cacheable && cacheGenerationAtStart === apiCacheGeneration) apiResponseCache.set(cacheKey, { data, expiresAt: Date.now() + 2500 });
    if (method !== 'GET') { apiCacheGeneration++; apiResponseCache.clear(); apiRequestsInFlight.clear(); }
    return data;
  })();
  if (!cacheable) return request;
  apiRequestsInFlight.set(cacheKey, request);
  try { return await request; }
  finally { if (apiRequestsInFlight.get(cacheKey) === request) apiRequestsInFlight.delete(cacheKey); }
}
function markViewLoaded(view) { viewLoadedAt[view] = Date.now(); }
function beginViewRequest(view) { const next = (viewRequestSequence[view] || 0) + 1; viewRequestSequence[view] = next; return next; }
function isCurrentViewRequest(view, requestId) { return viewRequestSequence[view] === requestId; }
function viewNeedsRefresh(view) { return Date.now() - (viewLoadedAt[view] || 0) >= VIEW_FRESHNESS_MS; }
function prefetchAppViews() {
  if (appPrefetchStarted || !currentUser) return;
  appPrefetchStarted = true;
  // Populate hidden views in the background so the first navigation is immediately useful.
  Promise.allSettled([loadLeaderboard(), loadDiscover(), loadFriends(), loadConversations(), loadChallenges(), loadProfile(), loadQuizzes()]);
}
function setButtonBusy(button, busy, busyText='Please wait…') {
  if(!button)return;
  if(busy){ if(!button.dataset.originalLabel)button.dataset.originalLabel=button.textContent.trim(); button.disabled=true; button.setAttribute('aria-busy','true'); button.innerHTML=`<span class="button-spinner" aria-hidden="true"></span>${escapeHtml(busyText)}`; }
  else { button.disabled=false; button.removeAttribute('aria-busy'); if(button.dataset.originalLabel){button.textContent=button.dataset.originalLabel;delete button.dataset.originalLabel;} }
}
function startPresenceHeartbeat(){if(presenceInterval)clearInterval(presenceInterval);if(!token)return;const ping=()=>{if(token)api('/api/me/presence',{method:'POST',body:{},timeoutMs:5000}).catch(()=>{});};ping();presenceInterval=setInterval(ping,60000);}
function stopPresenceHeartbeat(){if(presenceInterval)clearInterval(presenceInterval);presenceInterval=null;}
function showAuth(){ authGeneration++; quizLeaderboardRequestSequence++; publicProfileRequestSequence++; apiCacheGeneration++; apiResponseCache.clear(); apiRequestsInFlight.clear(); for(const key of Object.keys(viewLoadedAt))delete viewLoadedAt[key]; for(const key of Object.keys(viewRequestSequence))delete viewRequestSequence[key]; appPrefetchStarted=false; if(activeQuiz)closeQuizRunner(); stopPresenceHeartbeat(); if(quizRefreshInterval){clearInterval(quizRefreshInterval);quizRefreshInterval=null;} ['topLeaders','leaderboardList','discoverList','friendsList','incomingRequests','outgoingRequests','conversationList','challengeList','adminChallengeList','quizList','adminQuizList','quizLeaderboardList','adminUsersList','moderationList','moderationOverviewList'].forEach(id=>{const el=$(id);if(el)el.innerHTML='<div class="empty-state">Sign in to load this content.</div>';}); $('quizLeaderboardPanel').hidden=true; const profileDialog=$('publicProfileDialog'); if(profileDialog?.open)profileDialog.close(); if($('publicProfileContent'))$('publicProfileContent').innerHTML=''; $('profileForm')?.reset(); $('privacyForm')?.reset(); if(messageRefreshInterval){clearInterval(messageRefreshInterval);messageRefreshInterval=null;} selectedConversation=null; $('authPanel').hidden=false; $('appPanel').hidden=true; $('signOutButton').hidden=true; $('adminModerationPanel').hidden=true; $('quizAdminPanel').hidden=true; $('adminChallengePanel').hidden=true; currentUser=null; $('loginForm').hidden=false; $('registerForm').hidden=true; $('resetPasswordForm').hidden=true; setAuthTab('login'); }
function showApp(){ startPresenceHeartbeat(); $('authPanel').hidden=true; $('appPanel').hidden=false; $('signOutButton').hidden=false; $('adminNavButton').hidden=!Boolean(currentUser?.isAdmin); $('quizAdminPanel').hidden=!Boolean(currentUser?.isAdmin); $('adminChallengePanel').hidden=!Boolean(currentUser?.isAdmin); $('adminModerationPanel').hidden=!Boolean(currentUser?.isAdmin); renderQuickLinks(); prefetchAppViews(); }
function setAuthTab(tab){ document.querySelectorAll('[data-auth-tab]').forEach(b=>b.classList.toggle('active',b.dataset.authTab===tab)); $('loginForm').hidden=tab!=='login'; $('registerForm').hidden=tab!=='register'; }
function showView(view){
 document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
 document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==`view-${view}`);
 if(view==='leaderboard'&&viewNeedsRefresh('leaderboard'))loadLeaderboard();
 if(view==='quizzes'){if(viewNeedsRefresh('quizzes'))loadQuizzes();if(quizRefreshInterval)clearInterval(quizRefreshInterval);quizRefreshInterval=setInterval(()=>{if(!$('view-quizzes').hidden&&!activeQuiz)loadQuizzes();},15000);}else if(quizRefreshInterval){clearInterval(quizRefreshInterval);quizRefreshInterval=null;}
 if(view==='discover'&&viewNeedsRefresh('discover'))loadDiscover();
 if(view==='friends'&&viewNeedsRefresh('friends'))loadFriends();
 if(view==='messages'){
   if(viewNeedsRefresh('messages'))loadConversations();
   if(messageRefreshInterval)clearInterval(messageRefreshInterval);
   messageRefreshInterval=setInterval(()=>{if(!$('view-messages').hidden&&selectedConversation&&!document.hidden)loadMessages({quiet:true});},3000);
 }else if(messageRefreshInterval){clearInterval(messageRefreshInterval);messageRefreshInterval=null;}
 if(view==='challenges'&&viewNeedsRefresh('challenges'))loadChallenges();
 if(view==='profile'&&viewNeedsRefresh('profile'))loadProfile();
 if(view==='admin'&&currentUser?.isAdmin){loadAdminReports().catch(e=>toast(e.message));loadAdminUsers(1).catch(e=>toast(e.message));}
}
function avatar(user){ const name=escapeHtml(user.displayName||user.username||'?'); const img=user.avatarUrl ? `<img src="${escapeHtml(user.avatarUrl)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()">` : ''; return `<span class="avatar" aria-hidden="true">${img || name.slice(0,1).toUpperCase()}</span>`; }
