async function loadOverview(){if(!currentUser)return;const generation=authGeneration;const requestId=beginViewRequest('overview'); $('welcomeName').textContent=currentUser.displayName;const [stats,board,friends,challenges]=await Promise.allSettled([api('/api/me/stats?days=30'),api('/api/leaderboard?period=weekly'),api('/api/friends'),api('/api/challenges')]);if(generation!==authGeneration||!currentUser||!isCurrentViewRequest('overview',requestId))return;
  if(stats.status==='fulfilled'){const s=stats.value.stats;$('statHours').textContent=fmtTime(s.qualifyingSeconds);$('statLessons').textContent=String(s.completedEvents);$('statVideos').textContent=String(s.uniqueVideos);const badges=s.achievements?.achievements||[];$('achievementList').innerHTML=badges.length?badges.map(b=>`<span class="achievement">${escapeHtml(b.replaceAll('-',' '))}</span>`).join(''):'<span class="muted">Complete study sessions to earn badges.</span>';}
  if(board.status==='fulfilled'){$('topLeaders').innerHTML=board.value.leaderboard.slice(0,5).map(r=>rankRow(r,String(r.user.id)===String(currentUser.id))).join('')||'<div class="empty-state">No leaderboard activity yet. Connect Study Lock and complete a lesson.</div>';const me=board.value.leaderboard.find(r=>String(r.user.id)===String(currentUser.id));$('myRank').textContent=board.value.myRank?`#${board.value.myRank}`:'—';$('myPoints').textContent=me?me.points.toLocaleString():'0';}
  if(friends.status==='fulfilled')$('myFriends').textContent=String(friends.value.friends.length);
  if(challenges.status==='fulfilled')$('dashboardChallenges').innerHTML=challenges.value.challenges.slice(0,4).map(challengeCard).join('')||'<div class="empty-state">No current challenges yet.</div>';
}
async function loadLeaderboard(){const generation=authGeneration;const requestId=beginViewRequest('leaderboard');try{const period=$('leaderboardPeriod').value;const data=await api(`/api/leaderboard?period=${encodeURIComponent(period)}`);if(generation!==authGeneration||!currentUser||!isCurrentViewRequest('leaderboard',requestId))return;$('leaderboardList').innerHTML=data.leaderboard.map(r=>rankRow(r,String(r.user.id)===String(currentUser.id))).join('')||'<div class="empty-state">No one has opted into the leaderboard yet. Be the first to log study activity.</div>';$('leaderboardMeta').textContent=`Updated ${new Date(data.updatedAt).toLocaleString()}. ${data.pointsFormula}.`;if(data.myRank)$('myRank').textContent=`#${data.myRank}`;markViewLoaded('leaderboard');}catch(e){if(generation===authGeneration&&currentUser&&isCurrentViewRequest('leaderboard',requestId))$('leaderboardList').innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
async function loadDiscover(query=''){const generation=authGeneration;const requestId=beginViewRequest('discover');try{const data=await api(`/api/users${query?`?q=${encodeURIComponent(query)}`:''}`);if(generation!==authGeneration||!currentUser||!isCurrentViewRequest('discover',requestId))return;$('discoverList').innerHTML=data.users.map(u=>personCard(u,userButtons(u,u.isFriend,u.pendingRequest?'pending':''))).join('')||'<div class="empty-state">No public learners found. Try another username.</div>';if(!query)markViewLoaded('discover');}catch(e){if(generation===authGeneration&&currentUser&&isCurrentViewRequest('discover',requestId))$('discoverList').innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
