async function loadProfile(){const generation=authGeneration;const requestId=beginViewRequest('profile');try{const d=await api('/api/me');if(generation!==authGeneration||!currentUser||!isCurrentViewRequest('profile',requestId))return;currentUser=d.user;$('adminModerationPanel').hidden=!Boolean(d.user.isAdmin);$('adminNavButton').hidden=!Boolean(d.user.isAdmin);$('quizAdminPanel').hidden=!Boolean(d.user.isAdmin);$('adminChallengePanel').hidden=!Boolean(d.user.isAdmin);if(d.user.isAdmin){loadAdminReports().catch(()=>{});loadAdminQuizzes().catch(()=>{});loadAdminChallenges().catch(()=>{});}const form=$('profileForm');for(const key of ['displayName','phoneNumber','upiId','bio','avatarUrl'])form.elements[key].value=d.user[key]||'';form.elements.interests.value=(d.user.interests||[]).join(', ');form.elements.learningGoals.value=(d.user.learningGoals||[]).join(', ');const p=d.user.privacy||{};for(const key of ['profileVisibility','showOnLeaderboard','showStudyStats','allowFriendRequests','allowMessages'])form.elements[key].value=typeof p[key]==='undefined'?'':String(p[key]);for(const key of ['showOnLeaderboard','showStudyStats','allowFriendRequests'])form.elements[key].checked=p[key]!==false;form.elements.profileVisibility.value=p.profileVisibility||'public';form.elements.allowMessages.value=p.allowMessages||'friends';renderQuickLinks();markViewLoaded('profile');}catch(e){if(generation===authGeneration&&currentUser&&isCurrentViewRequest('profile',requestId))message('profileMessage',e.message);}}
async function showPublicProfile(username){const generation=authGeneration;const requestSequence=++publicProfileRequestSequence;$('publicProfileDialogTitle').textContent='Public profile';const dialog=$('publicProfileDialog');const content=$('publicProfileContent');content.innerHTML='<div class="empty-state">Loading profile…</div>';dialog.showModal();try{const [profile,stats]=await Promise.all([api(`/api/users/${encodeURIComponent(username)}`),api(`/api/users/${encodeURIComponent(username)}/stats`)]);if(generation!==authGeneration||!currentUser||requestSequence!==publicProfileRequestSequence)return;const u=profile.user;const achievements=(u.achievements||[]).map(x=>`<span class="achievement">${escapeHtml(x.replaceAll('-',' '))}</span>`).join('');const learningStats=stats.statsVisible?`<div class="metric-grid"><div class="metric"><small>STUDY TIME · 30 DAYS</small><b>${fmtTime(stats.stats.qualifyingSeconds)}</b></div><div class="metric"><small>COMPLETED LESSONS</small><b>${stats.stats.completedLessons}</b></div><div class="metric"><small>ACTIVE DAYS</small><b>${stats.stats.activeDays}</b></div></div>`:'<p class="muted">This learner keeps study stats private.</p>';content.innerHTML=`<div class="profile-cover">${avatar(u)}<div><h3>${escapeHtml(u.displayName)}</h3><p>@${escapeHtml(u.username)} · ${u.friendsCount||0} friends</p></div></div><p>${escapeHtml(u.bio||'No bio yet.')}</p><p>${(u.interests||[]).map(x=>`#${escapeHtml(x)}`).join(' ')}</p><h4>Learning goals</h4><p>${(u.learningGoals||[]).map(escapeHtml).join(' · ')||'Not shared'}</p><h4>Achievements</h4><div class="badge-list">${achievements||'<span class="muted">No achievements shared yet.</span>'}</div><h4>Public study stats</h4>${learningStats}<div class="person-actions">${!profile.isSelf&&!profile.isFriend?`<button class="btn primary" data-add-friend="${escapeHtml(u.username)}">Add friend</button>`:''}${!profile.isSelf&&profile.isFriend?`<button class="btn secondary" data-message-user="${escapeHtml(u.id)}" data-username="${escapeHtml(u.username)}">Message</button>`:''}${!profile.isSelf?`<button class="btn secondary" data-report-user="${escapeHtml(u.id)}">Report</button><button class="btn danger" data-block-user="${escapeHtml(u.id)}">Block</button>`:''}</div>`;}catch(e){if(generation===authGeneration&&currentUser&&requestSequence===publicProfileRequestSequence)content.innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
$('closeProfileDialog').addEventListener('click',()=>{publicProfileRequestSequence++;$('publicProfileDialog').close();});
async function requestFriend(username){await api('/api/friends/requests',{method:'POST',body:{username}});toast(`Friend request sent to @${username}.`);await loadDiscover($('discoverQuery').value.trim());}
async function blockUser(id){if(!confirm('Block this user? This removes the friendship, prevents new requests, and disables messaging.'))return;await api(`/api/blocks/${id}`,{method:'POST',body:{}});toast('User blocked.');selectedConversation=null;$('chatRoom').hidden=true;$('chatEmpty').hidden=false;await Promise.all([loadFriends(),loadDiscover(),loadConversations()]);}
async function reportTarget(type,id){const reason=prompt('Why are you reporting this? Enter spam, harassment, inappropriate, impersonation, or other:','other');if(!reason)return;const normal=reason.toLowerCase().trim();if(!['spam','harassment','inappropriate','impersonation','other'].includes(normal)){toast('Please use one of the listed reasons.');return;}const details=prompt('Optional details (do not include private information):','')||'';await api('/api/reports',{method:'POST',body:{targetType:type,targetId:id,reason:normal,details}});toast('Report sent for review.');}
async function acceptRequest(id){await api(`/api/friends/requests/${id}/accept`,{method:'POST',body:{}});toast('Friend request accepted.');await loadFriends();}
async function declineRequest(id){await api(`/api/friends/requests/${id}/decline`,{method:'POST',body:{}});toast('Request declined.');await loadFriends();}
async function removeFriend(id){if(!confirm('Remove this friend?'))return;await api(`/api/friends/${id}`,{method:'DELETE'});toast('Friend removed.');await loadFriends();}
async function joinChallenge(id, button){
 const card=button?.closest('.challenge-card');
 const originalMarkup=card?.innerHTML;
 beginViewRequest('challenges');beginViewRequest('overview');
 if(button){
   button.disabled=true;
   const actionArea=button.parentElement;
   if(actionArea){
     button.outerHTML=`<span class="achievement" data-optimistic-joined="${escapeHtml(id)}">Joined · 0%</span><button class="btn secondary small" data-refresh-challenge-progress="${escapeHtml(id)}">Refresh progress</button>`;
   }
   if(card){
     const participantLine=[...card.querySelectorAll('p')].find(p=>/\d+ participants/.test(p.textContent));
     if(participantLine)participantLine.textContent=participantLine.textContent.replace(/(\d+) participants/,(_,n)=>`${Number(n)+1} participants`);
   }
 }
 try{
   await api(`/api/challenges/${id}/join`,{method:'POST',body:{}});
   toast('Challenge joined.');
   // Keep the optimistic state visible; reconcile both challenge surfaces without blocking input.
   viewLoadedAt.challenges=0;
   void loadChallenges();
   void loadOverview();
 }catch(error){
   if(card&&originalMarkup!==undefined)card.innerHTML=originalMarkup;
   toast(error.message||'Could not join this challenge.');
 }
}
async function updateChallenge(id){await api(`/api/challenges/${id}/progress`,{method:'POST',body:{}});toast('Challenge progress refreshed from synced study activity.');await loadChallenges();}
function download(filename,text,mime){const blob=new Blob([text],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function exportData(){const [me,stats,friends,requests]=await Promise.all([api('/api/me'),api('/api/me/stats?days=90'),api('/api/friends'),api('/api/friends/requests')]);download('study-lock-community-data.json',JSON.stringify({exportedAt:new Date().toISOString(),profile:me,stats,friends,requests},null,2),'application/json');}
async function deleteAccount(){if(!confirm('Permanently delete your Study Lock Social account and associated data? This cannot be undone.'))return;const password=prompt('Enter your password to confirm permanent deletion:');if(password===null)return;await api('/api/me',{method:'DELETE',body:{password}});token='';localStorage.removeItem(TOKEN_KEY);showAuth();toast('Account deleted.');}

async function loadAdminReports(){if(!currentUser?.isAdmin)return;const generation=authGeneration;const requestId=beginViewRequest('adminReports');const data=await api('/api/admin/reports?status=open');if(generation!==authGeneration||!currentUser?.isAdmin||!isCurrentViewRequest('adminReports',requestId))return;const reportMarkup=data.reports.map(r=>`<article class="person-card"><b>${escapeHtml(r.reason)} · ${escapeHtml(r.targetType)}</b><p>Target: ${escapeHtml(r.targetId)} · Reporter: @${escapeHtml(r.reporter?.username||'deleted-user')}</p><p>${escapeHtml(r.details||'No additional details.')}</p><small>${dateFmt(r.createdAt)}</small><div class="person-actions"><button class="btn secondary small" data-report-status="reviewed" data-report-id="${escapeHtml(r.id)}">Mark reviewed</button><button class="btn primary small" data-report-status="actioned" data-report-id="${escapeHtml(r.id)}" data-target-type="${escapeHtml(r.targetType)}" data-target-id="${escapeHtml(r.targetId)}">Action</button><button class="btn secondary small" data-report-status="dismissed" data-report-id="${escapeHtml(r.id)}">Dismiss</button></div></article>`).join('')||'<div class="empty-state">No open reports.</div>';if($('moderationList'))$('moderationList').innerHTML=reportMarkup;if($('moderationOverviewList'))$('moderationOverviewList').innerHTML=reportMarkup;}// Personal quick-launch websites (CRUD). Saved links are HTTPS-only on the server.
function linksForDisplay(){if(currentUser?.quickLinksConfigured)return (Array.isArray(currentUser.quickLinks)?currentUser.quickLinks:[]).slice(0,10);return DEFAULT_QUICK_LINKS;}
function faviconFor(link){try{return `https://www.google.com/s2/favicons?domain=${encodeURIComponent(new URL(link.url).hostname)}&sz=64`;}catch{return '';}}
function renderQuickLinks(){if(!$('quickLinksList'))return;const links=linksForDisplay();$('quickLinksList').innerHTML=links.map((l,i)=>`<a class="quick-link" href="${escapeHtml(l.url)}" target="_blank" rel="noopener noreferrer" title="Open ${escapeHtml(l.label)} in a new tab"><span class="quick-link-icon"><img src="${escapeHtml(faviconFor(l))}" alt="" loading="lazy" onerror="this.style.display='none'"><span>${escapeHtml(l.icon||'🔗')}</span></span><b>${escapeHtml(l.label)}</b></a>`).join('');}
function renderQuickLinkManager(){const list=$('quickLinkManageList');if(!list)return;list.innerHTML=quickLinksDraft.map((l,i)=>`<div class="quick-link-manage-row"><span class="quick-link-manage-icon">${escapeHtml(l.icon||'🔗')}</span><div class="person-main"><b>${escapeHtml(l.label)}</b><small>${escapeHtml(l.url)}</small></div><button class="btn secondary small" type="button" data-edit-link="${i}">Edit</button><button class="btn danger small" type="button" data-delete-link="${i}">Delete</button></div>`).join('')||'<div class="empty-state">No saved links. Add a site above or save the default set.</div>';}
function openQuickLinkManager(){quickLinksDraft=linksForDisplay().map(l=>({label:String(l.label),url:String(l.url),icon:String(l.icon||'🔗')}));$('quickLinkManager').hidden=!$('quickLinkManager').hidden;if(!$('quickLinkManager').hidden)renderQuickLinkManager();}
$('manageQuickLinks').addEventListener('click',openQuickLinkManager);
$('quickLinkForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);const label=String(f.get('label')||'').trim();const url=String(f.get('url')||'').trim();const icon=String(f.get('icon')||'🔗').trim()||'🔗';try{const parsed=new URL(url);if(parsed.protocol!=='https:'||!parsed.hostname||parsed.username||parsed.password)throw new Error('Please use a valid HTTPS URL without embedded credentials.');if(!label)throw new Error('Enter a website name.');if(quickLinksDraft.length>=10)throw new Error('You can save up to 10 shortcuts.');if(quickLinksDraft.some(l=>new URL(l.url).toString()===parsed.toString()))throw new Error('That website is already in your shortcuts.');quickLinksDraft.push({label,url:parsed.toString(),icon});e.currentTarget.reset();renderQuickLinkManager();message('quickLinkMessage','Link added to the draft. Save to apply.',true);}catch(err){message('quickLinkMessage',err.message||'Enter a valid HTTPS website URL.');}});
$('saveQuickLinks').addEventListener('click',async()=>{try{const data=await api('/api/me',{method:'PATCH',body:{quickLinks:quickLinksDraft}});currentUser={...currentUser,...data.user};renderQuickLinks();renderQuickLinkManager();message('quickLinkMessage','Your shortcuts were saved.',true);toast('Quick links saved.');}catch(e){message('quickLinkMessage',e.message);}});

function toLocalInput(value){const d=new Date(value);if(!Number.isFinite(d.getTime()))return '';const local=new Date(d.getTime()-d.getTimezoneOffset()*60000);return local.toISOString().slice(0,16);}
function localInputIso(value){const d=new Date(value);if(!Number.isFinite(d.getTime()))throw new Error('Enter a valid date and time.');return d.toISOString();}
function defaultQuestion(){return {prompt:'',type:'single_choice',options:['Option A','Option B','Option C','Option D'],correctAnswers:['Option A'],points:1,timeLimitSeconds:30,explanation:''};}
function questionEditorMarkup(q={}){const id=`q_${Math.random().toString(36).slice(2,10)}`;const type=q.type||'single_choice';const options=Array.isArray(q.options)?q.options:[];const answers=Array.isArray(q.correctAnswers)?q.correctAnswers:[];return `<article class="question-editor" data-question-editor="${id}" id="editor_${id}"><div class="question-editor-heading"><b data-question-label>Question</b><button class="btn danger small" type="button" data-remove-question="${id}">Remove</button></div><label>Question prompt<textarea data-q-prompt rows="2" required minlength="3" maxlength="1000" placeholder="Type the question…">${escapeHtml(q.prompt||'')}</textarea></label><div class="two-col"><label>Question type<select data-q-type><option value="single_choice" ${type==='single_choice'?'selected':''}>Single choice</option><option value="multiple_choice" ${type==='multiple_choice'?'selected':''}>Multiple choice</option><option value="true_false" ${type==='true_false'?'selected':''}>True / false</option><option value="short_answer" ${type==='short_answer'?'selected':''}>Short answer</option></select></label><label>Points<input data-q-points type="number" min="1" max="100" value="${Number(q.points||1)}" required></label><label>Time for this question (seconds)<input data-q-time type="number" min="5" max="600" value="${Number(q.timeLimitSeconds||30)}" required></label></div><label data-q-options-wrap ${type==='short_answer'?'hidden':''}>Options (one per line)<textarea data-q-options rows="3" maxlength="2500" placeholder="Option A&#10;Option B">${escapeHtml((type==='true_false'?['True','False']:options).join('\n'))}</textarea></label><label>Correct answer(s)${type==='multiple_choice'?' (separate correct options with |)':type==='short_answer'?' (accepted variants separated with |)':''}<input data-q-correct required maxlength="1000" value="${escapeHtml(answers.join(' | '))}" placeholder="Enter the exact correct option or answer"></label><label>Explanation (optional)<textarea data-q-explanation rows="2" maxlength="1000" placeholder="Explain the answer after the quiz…">${escapeHtml(q.explanation||'')}</textarea></label></article>`;}
function renderQuestionEditorNav(){const nav=$('questionEditorNav');if(!nav)return;const editors=[...$('questionEditors').querySelectorAll('[data-question-editor]')];editors.forEach((editor,index)=>{const label=editor.querySelector('[data-question-label]');if(label)label.textContent=`Question ${index+1}`;});nav.innerHTML=editors.map((editor,index)=>`<button class="question-editor-jump" type="button" data-goto-question="${escapeHtml(editor.dataset.questionEditor)}" aria-label="Jump to question ${index+1}">Q${index+1}</button>`).join('');nav.hidden=editors.length<2;}
function addQuestionEditor(q=defaultQuestion()){if($('questionEditors').children.length>=100){toast('A quiz can contain at most 100 questions.');return;}$('questionEditors').insertAdjacentHTML('beforeend',questionEditorMarkup(q));const editor=$('questionEditors').lastElementChild;const type=editor.querySelector('[data-q-type]');const options=editor.querySelector('[data-q-options]');const wrap=editor.querySelector('[data-q-options-wrap]');type.addEventListener('change',()=>{const answer=editor.querySelector('[data-q-correct]');wrap.hidden=type.value==='short_answer';if(type.value==='true_false'){options.value='True\nFalse';answer.value='True';}else if(type.value==='short_answer'){options.value='';answer.value='';}else{if(options.value==='True\nFalse'||!options.value.trim())options.value='Option A\nOption B\nOption C\nOption D';answer.value='Option A';}});renderQuestionEditorNav();}
$('questionEditorNav').addEventListener('click',e=>{const button=e.target.closest('[data-goto-question]');if(!button)return;const target=document.querySelector(`[data-question-editor="${CSS.escape(button.dataset.gotoQuestion)}"]`);target?.scrollIntoView({behavior:'smooth',block:'start'});});
function collectQuestionEditors(){return [...$('questionEditors').querySelectorAll('[data-question-editor]')].map((el,index)=>{const type=el.querySelector('[data-q-type]').value;const options=type==='true_false'?['True','False']:type==='short_answer'?[]:el.querySelector('[data-q-options]').value.split('\n').map(x=>x.trim()).filter(Boolean);const correctAnswers=el.querySelector('[data-q-correct]').value.split('|').map(x=>x.trim()).filter(Boolean);return {prompt:el.querySelector('[data-q-prompt]').value.trim(),type,options,correctAnswers,points:Number(el.querySelector('[data-q-points]').value),timeLimitSeconds:Number(el.querySelector('[data-q-time]').value),explanation:el.querySelector('[data-q-explanation]').value.trim()};});}
function resetQuizEditor(){const form=$('quizForm');form.reset();form.elements.quizId.value='';form.elements.isPublished.checked=true;form.elements.maxParticipants.value='100';form.elements.durationMinutes.value='30';$('quizEditorHeading').textContent='Create a quiz';$('quizAdminMessage').textContent='';$('questionEditors').innerHTML='';addQuestionEditor();}
function fillQuizEditor(q){const f=$('quizForm');f.elements.quizId.value=q.id;f.elements.title.value=q.title;f.elements.description.value=q.description||'';f.elements.startsAt.value=toLocalInput(q.startsAt);f.elements.endsAt.value=toLocalInput(q.endsAt);f.elements.durationMinutes.value=q.durationMinutes;f.elements.maxParticipants.value=q.maxParticipants;f.elements.isPublished.checked=Boolean(q.isPublished);$('quizEditorHeading').textContent=`Edit quiz: ${q.title}`;$('questionEditors').innerHTML='';(q.questionDetails||[]).forEach(x=>addQuestionEditor({...x,correctAnswers:x.correctAnswers||[]}));if(!q.questionDetails?.length)addQuestionEditor();$('quizAdminMessage').textContent='';window.scrollTo({top:$('quizAdminPanel').getBoundingClientRect().top+window.scrollY-90,behavior:'smooth'});}
function quizCard(q){const attempt=q.attempt;let action='';if(attempt?.status==='in_progress')action=`<button class="btn primary small" data-start-quiz="${escapeHtml(q.id)}">Continue attempt</button>`;else if(attempt?.status==='disqualified')action='<button class="btn danger small" disabled>Disqualified</button>';else if(q.state==='upcoming'){if(q.isRegistered)action=`<button class="btn secondary small" disabled>Registered · opens ${escapeHtml(dateFmt(q.startsAt))}</button>`;else action=q.participantCount>=q.maxParticipants?'<button class="btn secondary small" disabled>Quiz full</button>':`<button class="btn primary small" data-register-quiz="${escapeHtml(q.id)}">Register for quiz</button>`;}else if(q.state==='open'&&!attempt){action=q.isRegistered?`<button class="btn primary small" data-start-quiz="${escapeHtml(q.id)}">Start quiz</button>`:'<button class="btn secondary small" disabled>Registration closed</button>';}else if(q.state==='ended')action=`<button class="btn primary small" data-quiz-board="${escapeHtml(q.id)}">View leaderboard</button>`;else if(attempt)action='<button class="btn secondary small" disabled>Submitted · awaiting results</button>';else action='<button class="btn secondary small" disabled>Not available</button>';const prize=attempt?.prizeAwarded&&!attempt?.prizeReceived?`<p class="prize-pending">🏅 Cash prize selected: ₹${Number(attempt.prizeAmount||0).toLocaleString('en-IN')} <button class="btn primary small" data-confirm-prize="${escapeHtml(q.id)}">Confirm prize received</button></p>`:attempt?.prizeReceived?`<p class="prize-confirmed">✓ Prize receipt confirmed: ₹${Number(attempt.prizeAmount||0).toLocaleString('en-IN')}</p>`:'';const stateLabel=q.state==='open'?'OPEN NOW':q.state==='upcoming'?'UPCOMING':'RESULTS PUBLISHED';return `<article class="quiz-card"><div class="quiz-card-top"><span class="challenge-meta">${stateLabel}</span><span class="quiz-capacity">${q.participantCount}/${q.maxParticipants} registered</span></div><h4>${escapeHtml(q.title)}</h4><p>${escapeHtml(q.description||'An admin-created timed quiz.')}</p><div class="quiz-meta-grid"><span><small>QUESTIONS</small><b>${q.questionCount}</b></span><span><small>MAX SCORE</small><b>${q.totalPoints}</b></span><span><small>TIME LIMIT</small><b>${q.durationMinutes} min</b></span></div><p class="muted">${q.state==='ended'?'Closed':`Starts ${dateFmt(q.startsAt)}`} · Ends ${dateFmt(q.endsAt)}</p>${attempt&&q.state==='ended'&&attempt.score!==undefined?`<p class="quiz-own-score">Your score: <b>${attempt.score}/${q.totalPoints}</b></p>`:''}${prize}<div class="person-actions">${action}</div></article>`;}
async function loadQuizzes(){const generation=authGeneration;const requestId=beginViewRequest('quizzes');try{const d=await api('/api/quizzes');if(generation!==authGeneration||!currentUser||!isCurrentViewRequest('quizzes',requestId))return;$('quizList').innerHTML=d.quizzes.map(quizCard).join('')||'<div class="empty-state">No quizzes have been published yet. Check back soon.</div>';markViewLoaded('quizzes');if(currentUser?.isAdmin){$('quizAdminPanel').hidden=false;await loadAdminQuizzes();}}catch(e){if(generation===authGeneration&&currentUser&&isCurrentViewRequest('quizzes',requestId))$('quizList').innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
async function loadAdminQuizzes(){if(!currentUser?.isAdmin)return;const generation=authGeneration;const requestId=beginViewRequest('adminQuizzes');try{const d=await api('/api/admin/quizzes');if(generation!==authGeneration||!currentUser?.isAdmin||!isCurrentViewRequest('adminQuizzes',requestId))return;$('adminQuizList').innerHTML=d.quizzes.map(q=>`<article class="admin-quiz-row"><div class="person-main"><b>${escapeHtml(q.title)}</b><small>${escapeHtml(q.state)} · ${q.attemptCount} attempt(s) · ${q.participantCount}/${q.maxParticipants} seats · ${q.questionCount} questions</small><small>${dateFmt(q.startsAt)} – ${dateFmt(q.endsAt)}</small></div><div class="person-actions"><button class="btn secondary small" data-edit-quiz="${escapeHtml(q.id)}" ${(q.attemptCount>0||q.participantCount>0)?'disabled title="Quiz questions and schedule lock after registration"':''}>Edit</button><button class="btn secondary small" data-toggle-quiz="${escapeHtml(q.id)}" data-published="${q.isPublished?'true':'false'}" ${(q.isPublished&&(q.attemptCount>0||q.participantCount>0))?'disabled title="Cannot hide a quiz after registration; public results must remain available"':''}>${q.isPublished?'Published':'Publish'}</button><button class="btn secondary small" data-admin-quiz-board="${escapeHtml(q.id)}" ${q.state!=='ended'?'disabled':''}>Leaderboard</button><button class="btn danger small" data-delete-quiz="${escapeHtml(q.id)}" ${(q.attemptCount>0||q.participantCount>0)?'disabled title="A quiz with participants or attempts cannot be deleted"':''}>Delete</button></div></article>`).join('')||'<div class="empty-state">No quizzes created yet.</div>';window._adminQuizCache=d.quizzes;}catch(e){if(generation===authGeneration&&currentUser?.isAdmin&&isCurrentViewRequest('adminQuizzes',requestId))$('adminQuizList').innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
$('addQuestionButton').addEventListener('click',()=>addQuestionEditor());
$('resetQuizForm').addEventListener('click',resetQuizEditor);
$('closeQuizLeaderboard').addEventListener('click',()=>{ quizLeaderboardRequestSequence++; $('quizLeaderboardPanel').hidden=true; $('quizList').scrollIntoView({behavior:'smooth',block:'start'}); });
$('refreshQuizzes').addEventListener('click',loadQuizzes);
$('refreshAdminQuizzes').addEventListener('click',loadAdminQuizzes);
$('quizForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const id=String(f.get('quizId')||'');try{const body={title:f.get('title'),description:f.get('description'),startsAt:localInputIso(f.get('startsAt')),endsAt:localInputIso(f.get('endsAt')),durationMinutes:Number(f.get('durationMinutes')),maxParticipants:Number(f.get('maxParticipants')),isPublished:f.get('isPublished')==='on',questions:collectQuestionEditors()};const path=id?`/api/admin/quizzes/${id}`:'/api/admin/quizzes';const result=await api(path,{method:id?'PATCH':'POST',body});message('quizAdminMessage',result.message||'Quiz saved.',true);resetQuizEditor();await Promise.all([loadQuizzes(),loadAdminQuizzes()]);}catch(err){message('quizAdminMessage',err.message);}});

function runnerAnswerFor(question, answers){return (answers||[]).find(a=>String(a.questionId)===String(question.id))?.response||[];}
function paintQuizWarningCount(){
 if(!activeQuiz)return;
 const label=$('quizWarningCount');
 if(label){const count=Number(activeQuiz.copyWarnings||0);label.textContent=count>=3?'Copy warnings used: 3 of 3 · next copy violation disqualifies you':`Copy warnings used: ${count} of 3`;label.classList.toggle('warning-limit',count>=3);}
 const fullscreenLabel=$('quizFullscreenWarningCount');
 if(fullscreenLabel){const count=Number(activeQuiz.fullscreenViolations||0);fullscreenLabel.textContent=count>=3?'Fullscreen warnings used: 3 of 3 · next fullscreen/focus violation disqualifies you':`Fullscreen warnings used: ${count} of 3`;fullscreenLabel.classList.toggle('warning-limit',count>=3);}
}
function showFullscreenGate(messageText='This quiz must remain in fullscreen mode. Return to fullscreen to continue.'){
 const gate=$('quizFullscreenGate');if(!gate)return;
 $('quizFullscreenGateMessage').textContent=messageText;
 gate.hidden=false;
}
function hideFullscreenGate(){const gate=$('quizFullscreenGate');if(gate)gate.hidden=true;}
function currentFullscreenElement(){return document.fullscreenElement||document.webkitFullscreenElement||null;}
async function enterQuizFullscreen(){
 if(currentFullscreenElement())return true;
 const root=document.documentElement;
 const requestFullscreen=root.requestFullscreen||root.webkitRequestFullscreen||root.webkitRequestFullScreen;
 if(typeof requestFullscreen!=='function'){toast('This browser does not support required fullscreen quizzes. Open the quiz in a browser with Fullscreen API support.');return false;}
 try{
   // Call requestFullscreen synchronously from the Start/Resume button gesture.
   try{await requestFullscreen.call(root,{navigationUI:'hide'});}
   catch(firstError){
     // Some older implementations reject the optional navigationUI dictionary.
     if(!currentFullscreenElement())await requestFullscreen.call(root);else throw firstError;
   }
   if(!currentFullscreenElement())throw new Error('Fullscreen was not activated.');
   return true;
 }catch(error){toast('Fullscreen is required to take this quiz. Allow fullscreen and select Start quiz again.');return false;}
}
async function exitQuizFullscreen(){
 try{const exit=document.exitFullscreen||document.webkitExitFullscreen;if(currentFullscreenElement()&&typeof exit==='function')await exit.call(document);}catch{/* Browser may already have exited fullscreen. */}
}
function closeQuizRunner(){
 clearInterval(quizTimerInterval);clearTimeout(quizAutosaveTimer);
 if($('quizDialog').open)$('quizDialog').close();
 activeQuiz=null;hideFullscreenGate();
 void exitQuizFullscreen();
}
async function resumeQuizFullscreen(){
 if(!activeQuiz)return;
 if(currentFullscreenElement()){activeQuiz.fullscreenInterruption=false;hideFullscreenGate();scheduleQuizAutosave();return;}
 const entered=await enterQuizFullscreen();
 if(entered&&activeQuiz){activeQuiz.fullscreenInterruption=false;hideFullscreenGate();scheduleQuizAutosave();toast('Fullscreen restored. Continue your quiz.');}
}
function applyRunnerPayload(data, initial=false){
  if(!activeQuiz)return;
  if(data.submitted || data.attempt?.status && data.attempt.status!=='in_progress'){
    const wasDisqualified=data.attempt?.status==='disqualified';const reason=String(data.attempt?.disqualificationReason||'');const id=activeQuiz.id;closeQuizRunner();toast(wasDisqualified?(reason.includes('fullscreen')||reason.includes('focus')?'You were disqualified after repeated fullscreen/focus violations.':'You were disqualified after the fourth quiz integrity violation.'):'Your quiz attempt has ended.');void loadQuizzes();return;
  }
  activeQuiz.deadlineAt=data.quiz.deadlineAt;activeQuiz.questionDeadlineAt=data.quiz.questionDeadlineAt;activeQuiz.questionStartedAt=data.quiz.questionStartedAt;activeQuiz.questionCount=data.quiz.questionCount;activeQuiz.currentQuestionIndex=data.quiz.currentQuestionIndex;activeQuiz.question=data.quiz.question;activeQuiz.answers=data.attempt.answers||[];activeQuiz.copyWarnings=Number(data.attempt.copyWarnings||0);activeQuiz.fullscreenViolations=Number(data.attempt.fullscreenViolations||0);activeQuiz.advancing=false;
  paintQuizWarningCount();paintCurrentQuizQuestion();if(initial&&!$('quizDialog').open)$('quizDialog').showModal();if(currentFullscreenElement())hideFullscreenGate();else showFullscreenGate('Fullscreen is required to continue. Return to fullscreen; question timers continue to run.');startQuizClock();
}
function paintCurrentQuizQuestion(){if(!activeQuiz?.question)return;const q=activeQuiz.question;const val=runnerAnswerFor(q,activeQuiz.answers);let controls='';if(q.type==='short_answer')controls=`<input type="text" data-answer-question="${escapeHtml(q.id)}" data-answer-kind="text" maxlength="1000" autocomplete="off" value="${escapeHtml(val[0]||'')}" placeholder="Type your answer…">`;else controls=(q.options||[]).map(opt=>{const type=q.type==='multiple_choice'?'checkbox':'radio';const checked=val.some(v=>v.toLocaleLowerCase()===opt.toLocaleLowerCase());return `<label class="quiz-option"><input type="${type}" name="q_${escapeHtml(q.id)}" value="${escapeHtml(opt)}" data-answer-question="${escapeHtml(q.id)}" ${checked?'checked':''}><span>${escapeHtml(opt)}</span></label>`;}).join('');$('quizRunnerTitle').textContent=activeQuiz.title;$('quizRunnerDescription').textContent='Your answer is saved automatically. The server controls each question timer.';$('quizQuestionProgress').textContent=`Question ${activeQuiz.currentQuestionIndex+1} of ${activeQuiz.questionCount}`;$('quizQuestionProgressBar').style.width=`${((activeQuiz.currentQuestionIndex+1)/activeQuiz.questionCount)*100}%`;$('quizRunnerQuestions').innerHTML=`<article class="quiz-question" oncopy="return false"><div class="quiz-question-heading"><span>QUESTION ${activeQuiz.currentQuestionIndex+1}</span><b>${q.points} point${q.points===1?'':'s'} · ${q.timeLimitSeconds}s</b></div><h4>${escapeHtml(q.prompt)}</h4><div class="quiz-answer-options">${controls}</div></article>`;$('submitQuizButton').textContent=activeQuiz.currentQuestionIndex+1>=activeQuiz.questionCount?'Finish quiz':'Save & continue';$('submitQuizButton').disabled=false;$('quizRunnerStatus').textContent='';}
function collectCurrentResponse(){const q=activeQuiz?.question;if(!q)return [];if(q.type==='short_answer'){const el=$('quizRunnerQuestions').querySelector(`[data-answer-question="${CSS.escape(String(q.id))}"][data-answer-kind="text"]`);return el?.value.trim()?[el.value.trim()]:[];}return [...$('quizRunnerQuestions').querySelectorAll(`[data-answer-question="${CSS.escape(String(q.id))}"]:checked`)].map(el=>el.value);}
async function saveOnlyCurrentAnswer(){if(!activeQuiz||!$('quizFullscreenGate').hidden||activeQuiz.advancing||quizAutosaveBusy||Date.now()>=new Date(activeQuiz.questionDeadlineAt).getTime())return;const quizId=activeQuiz.id;const questionId=activeQuiz.question.id;const response=collectCurrentResponse();quizAutosaveBusy=true;try{const d=await api(`/api/quizzes/${quizId}/attempt`,{method:'PUT',body:{questionId,response,saveOnly:true,fullscreenConfirmed:true}});if(activeQuiz?.id===quizId&&String(activeQuiz.question?.id)===String(questionId)&&!d.questionTimedOut){activeQuiz.answers=d.attempt?.answers||activeQuiz.answers;message('quizRunnerStatus','Answer saved.',true);}}catch(e){if(activeQuiz)message('quizRunnerStatus',e.message);}finally{quizAutosaveBusy=false;}}
function scheduleQuizAutosave(){if(!activeQuiz||!$('quizFullscreenGate').hidden||activeQuiz.advancing)return;clearTimeout(quizAutosaveTimer);quizAutosaveTimer=setTimeout(()=>saveOnlyCurrentAnswer(),250);}
async function advanceQuizQuestion(auto=false){if(!activeQuiz||activeQuiz.advancing||(!auto&&!$('quizFullscreenGate').hidden))return;activeQuiz.advancing=true;clearTimeout(quizAutosaveTimer);const button=$('submitQuizButton');setButtonBusy(button,true,auto?'Time ended…':'Saving…');message('quizRunnerStatus',auto?'Question time ended. Loading the next question…':'Saving your answer…');try{for(let i=0;quizAutosaveBusy&&i<30;i++)await new Promise(resolve=>setTimeout(resolve,50));const id=activeQuiz.id;const q=activeQuiz.question;const response=auto?[]:collectCurrentResponse();const d=await api(`/api/quizzes/${id}/attempt`,{method:'PUT',body:{questionId:q.id,response,skip:auto,fullscreenConfirmed:true}});if(!activeQuiz||activeQuiz.id!==id)return;if(d.disqualified){closeQuizRunner();toast('You were disqualified from this quiz.');void loadQuizzes();return;}if(d.submitted||d.attempt?.status!=='in_progress'){applyRunnerPayload(d);return;}if(d.questionTimedOut)toast('Question time expired. The question was skipped.');applyRunnerPayload(d);}catch(e){if(activeQuiz&&auto&&e.message.includes('question timer has not expired')){activeQuiz.advancing=false;setTimeout(()=>advanceQuizQuestion(true),200);return;}if(activeQuiz){activeQuiz.advancing=false;message('quizRunnerStatus',e.message);}}finally{if(activeQuiz){activeQuiz.advancing=false;setButtonBusy(button,false);if(activeQuiz.currentQuestionIndex+1>=activeQuiz.questionCount)button.textContent='Finish quiz';else button.textContent='Save & continue';}else setButtonBusy(button,false);}}
function startQuizClock(){clearInterval(quizTimerInterval);const update=()=>{if(!activeQuiz)return;const overall=Math.max(0,Math.ceil((new Date(activeQuiz.deadlineAt).getTime()-Date.now())/1000));const mins=Math.floor(overall/60),secs=overall%60;$('quizTimer').textContent=`${String(mins).padStart(2,'0')}:${String(secs).padStart(2,'0')}`;$('quizTimer').classList.toggle('urgent',overall<=60);const questionLeft=Math.max(0,Math.ceil((new Date(activeQuiz.questionDeadlineAt).getTime()-Date.now())/1000));$('questionTimer').textContent=`${questionLeft}s`; $('questionTimer').classList.toggle('urgent',questionLeft<=5);if(overall<=0){clearInterval(quizTimerInterval);submitQuizAttempt(true).catch(e=>toast(e.message));}else if(questionLeft<=0){clearInterval(quizTimerInterval);advanceQuizQuestion(true).catch(e=>toast(e.message));}};update();quizTimerInterval=setInterval(update,250);}
async function startQuiz(id){
 const enteredFullscreen=await enterQuizFullscreen();
 if(!enteredFullscreen)return;
 try{
   const d=await api(`/api/quizzes/${id}/start`,{method:'POST',body:{fullscreenConfirmed:true}});
   if(d.submitted||d.attempt?.status&&d.attempt.status!=='in_progress'){
     toast(d.attempt?.status==='disqualified'?'This attempt was disqualified.':'Your quiz attempt has already ended.');
     await exitQuizFullscreen();await loadQuizzes();return;
   }
   activeQuiz={id:d.quiz.id,title:d.quiz.title,answers:d.attempt.answers||[],copyWarnings:d.attempt.copyWarnings||0,fullscreenViolations:d.attempt.fullscreenViolations||0,fullscreenInterruption:false};
   applyRunnerPayload(d,true);
   if(!currentFullscreenElement()){showFullscreenGate('Fullscreen ended while the quiz was opening. Return to fullscreen to continue.');activeQuiz.fullscreenInterruption=true;void reportQuizViolation('fullscreen_exit');}
 }catch(e){toast(e.message);if(!activeQuiz)await exitQuizFullscreen();await loadQuizzes();}
}
async function registerForQuiz(id,button){setButtonBusy(button,true,'Registering…');try{const d=await api(`/api/quizzes/${id}/register`,{method:'POST',body:{}});toast(d.message||'Registration complete.');await loadQuizzes();}catch(e){toast(e.message);}finally{setButtonBusy(button,false);}}
async function submitQuizAttempt(auto=false){if(!activeQuiz)return;const quizId=activeQuiz.id;clearInterval(quizTimerInterval);clearTimeout(quizAutosaveTimer);const button=$('submitQuizButton');setButtonBusy(button,true,auto?'Submitting…':'Finishing…');message('quizRunnerStatus',auto?'Overall time ended. Submitting saved answers…':'Finishing quiz…');try{for(let i=0;quizAutosaveBusy&&i<30;i++)await new Promise(resolve=>setTimeout(resolve,50));const q=activeQuiz?.question;const body=auto?{fullscreenConfirmed:true}:{questionId:q?.id,response:collectCurrentResponse(),fullscreenConfirmed:true};const d=await api(`/api/quizzes/${quizId}/submit`,{method:'POST',body});closeQuizRunner();toast(d.status==='disqualified'?'You were disqualified from this quiz.':d.message||'Quiz submitted.');await loadQuizzes();if(d.resultsPublished)await showQuizLeaderboard(quizId);}catch(e){message('quizRunnerStatus',e.message);if(auto){closeQuizRunner();await loadQuizzes();toast(e.message);}}finally{setButtonBusy(button,false);}}
$('quizRunnerForm').addEventListener('change',scheduleQuizAutosave);
$('quizRunnerForm').addEventListener('input',scheduleQuizAutosave);
$('quizRunnerForm').addEventListener('submit',e=>{e.preventDefault();if(!$('quizFullscreenGate').hidden)return;advanceQuizQuestion(false);});
$('closeQuizDialog').addEventListener('click',()=>{if(!activeQuiz)return;if(!confirm('Leave this attempt? Your server timer will continue, and you can resume before time runs out.'))return;closeQuizRunner();void loadQuizzes();});
$('resumeQuizFullscreen').addEventListener('click',resumeQuizFullscreen);
$('quizDialog').addEventListener('cancel',e=>{e.preventDefault();$('closeQuizDialog').click();});
async function reportQuizViolation(type){
 if(!activeQuiz)return;
 const fullscreenViolation=['fullscreen_exit','focus_lost'].includes(type);
 const quizId=activeQuiz.id;
 try{
   const d=await api(`/api/quizzes/${quizId}/attempt/violation`,{method:'POST',body:{type}});
   if(!activeQuiz||activeQuiz.id!==quizId)return;
   if(d.disqualified||d.submitted||d.status&&d.status!=='in_progress'){
     closeQuizRunner();
     toast(d.disqualified?(d.message||'You have been disqualified.'):'Your quiz attempt has ended.');
     void loadQuizzes();return;
   }
   if(d.warnings!==undefined){if(fullscreenViolation)activeQuiz.fullscreenViolations=Math.max(Number(activeQuiz.fullscreenViolations||0),Number(d.warnings));else activeQuiz.copyWarnings=Math.max(Number(activeQuiz.copyWarnings||0),Number(d.warnings));}
   paintQuizWarningCount();toast(d.message||(fullscreenViolation?`Fullscreen warning ${d.warnings||''} of 3.`:`Copy warning ${d.warnings||''} of 3.`));
 }catch(e){if(activeQuiz&&activeQuiz.id===quizId)message('quizRunnerStatus',e.message);}
}
document.addEventListener('keydown',e=>{if(!activeQuiz||!$('quizDialog').open)return;if(!$('quizFullscreenGate').hidden){if(!e.target.closest('#resumeQuizFullscreen')){e.preventDefault();e.stopPropagation();}return;}const key=String(e.key||'').toLowerCase();if((e.ctrlKey||e.metaKey)&&['c','x','p'].includes(key)){e.preventDefault();e.stopPropagation();reportQuizViolation(key==='c'?'keyboard_copy':key==='x'?'cut':'print');}else if((e.ctrlKey||e.metaKey)&&key==='a'&&e.target.closest('.quiz-question')){e.preventDefault();}},true);
document.addEventListener('copy',e=>{if(activeQuiz&&$('quizDialog').open&&!$('quizFullscreenGate').hidden)return;if(activeQuiz&&$('quizDialog').open){e.preventDefault();reportQuizViolation('copy');}},true);
document.addEventListener('cut',e=>{if(activeQuiz&&$('quizDialog').open){e.preventDefault();reportQuizViolation('cut');}},true);
document.addEventListener('contextmenu',e=>{if(activeQuiz&&$('quizDialog').open){e.preventDefault();reportQuizViolation('contextmenu');}},true);
document.addEventListener('fullscreenchange',()=>{
 if(!activeQuiz||!$('quizDialog').open)return;
 if(currentFullscreenElement()){return;}
 showFullscreenGate('Fullscreen was exited. Your quiz is paused until you return to fullscreen. Each exit/focus interruption counts as an integrity warning; a fourth violation disqualifies this attempt.');
 if(!activeQuiz.fullscreenInterruption){activeQuiz.fullscreenInterruption=true;void reportQuizViolation('fullscreen_exit');}
});
document.addEventListener('webkitfullscreenchange',()=>{
 if(!activeQuiz||!$('quizDialog').open||currentFullscreenElement())return;
 showFullscreenGate('Fullscreen was exited. Your quiz is paused until you return to fullscreen. Each exit/focus interruption counts as an integrity warning; a fourth violation disqualifies this attempt.');
 if(!activeQuiz.fullscreenInterruption){activeQuiz.fullscreenInterruption=true;void reportQuizViolation('fullscreen_exit');}
});
document.addEventListener('visibilitychange',()=>{
 if(!activeQuiz||!$('quizDialog').open||document.visibilityState!=='hidden')return;
 showFullscreenGate('The quiz tab lost focus. Return to this page and restore fullscreen before continuing.');
 if(!activeQuiz.fullscreenInterruption){activeQuiz.fullscreenInterruption=true;void reportQuizViolation('focus_lost');}
});
async function showQuizLeaderboard(quizId){const generation=authGeneration;const requestSequence=++quizLeaderboardRequestSequence;try{const d=await api(`/api/quizzes/${quizId}/leaderboard`);if(generation!==authGeneration||!currentUser||requestSequence!==quizLeaderboardRequestSequence)return;$('quizLeaderboardPanel').hidden=false;$('quizLeaderboardTitle').textContent=`${d.quiz.title} leaderboard`;$('quizLeaderboardRules').textContent=d.rules;$('quizLeaderboardList').innerHTML=d.leaderboard.map(row=>{const prize=row.prize?`<span class="prize-confirmed">🏆 Cash prize received: ₹${Number(row.prize.amount||0).toLocaleString('en-IN')}${row.prize.note?` · ${escapeHtml(row.prize.note)}`:''}</span>`:'';const adminActions=currentUser?.isAdmin?`<button class="btn secondary small" data-admin-profile="${escapeHtml(quizId)}" data-attempt-profile="${escapeHtml(row.attemptId)}">Full profile</button><button class="btn ${row.prizeAwarded?'secondary':'primary'} small" data-award-prize="${escapeHtml(quizId)}" data-prize-attempt="${escapeHtml(row.attemptId)}" data-prize-awarded="${row.prizeAwarded?'true':'false'}" data-prize-amount="${Number(row.prizeAmount||0)}">${row.prizeAwarded?'Edit prize':'Mark cash prize'}</button>`:'';return `<div class="quiz-rank-row"><span class="rank-num">#${row.rank}</span>${avatar(row.user)}<div class="person-main"><b>${escapeHtml(row.user.displayName)}</b><small>@${escapeHtml(row.user.username)} · ${row.score}/${row.totalPoints} points · ${Math.floor(row.elapsedSeconds/60)}m ${row.elapsedSeconds%60}s</small>${prize}</div>${adminActions}</div>`;}).join('')||'<div class="empty-state">No completed attempts are available for this quiz.</div>';window._activeLeaderboardQuiz=quizId;markViewLoaded('quizLeaderboard');}catch(e){if(generation===authGeneration&&currentUser&&requestSequence===quizLeaderboardRequestSequence)toast(e.message);}}
async function loadAdminUsers(page=adminUserPage){if(!currentUser?.isAdmin)return;const generation=authGeneration;const requestId=beginViewRequest('adminUsers');adminUserPage=Math.max(1,page);const list=$('adminUsersList');list.innerHTML='<div class="loading-row"><span class="button-spinner"></span>Loading users…</div>';try{const q=$('adminUsersSearch').value.trim();const d=await api(`/api/admin/users?page=${adminUserPage}&limit=50&q=${encodeURIComponent(q)}`);if(generation!==authGeneration||!currentUser?.isAdmin||!isCurrentViewRequest('adminUsers',requestId))return;adminUserPage=d.page;adminUserTotalPages=d.totalPages;$('adminUsersPageLabel').textContent=`Page ${d.page} of ${d.totalPages} · ${d.total} users`;$('adminUsersPrev').disabled=d.page<=1;$('adminUsersNext').disabled=d.page>=d.totalPages;list.innerHTML=d.users.map(u=>`<div class="person-row admin-user-row">${avatar(u)}<div class="person-main"><b>${escapeHtml(u.displayName)} <span class="muted">@${escapeHtml(u.username)}</span></b><small>${escapeHtml(u.role)} · Joined ${dateFmt(u.createdAt)} · Last seen ${u.lastActiveAt?dateFmt(u.lastActiveAt):'Never'}</small><div class="user-status-tags"><span class="status-pill ${u.loggedIn?'online':'offline'}">${u.loggedIn?'Logged in':'Not recently online'}</span><span class="status-pill ${u.isActive?'active':'inactive'}">${u.isActive?'Active':'Inactive (30+ days)'}</span>${u.emailVerified?'<span class="status-pill active">Email verified</span>':'<span class="status-pill offline">Email unverified</span>'}${u.suspended?'<span class="status-pill offline">Suspended</span>':''}</div></div><button class="btn primary small" type="button" data-admin-user-profile="${escapeHtml(u.id)}">Profile</button></div>`).join('')||'<div class="empty-state">No users match this search.</div>';}catch(e){if(generation===authGeneration&&currentUser?.isAdmin&&isCurrentViewRequest('adminUsers',requestId))list.innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
async function showAdminUserProfile(userId){const generation=authGeneration;const requestSequence=++publicProfileRequestSequence;$('publicProfileDialogTitle').textContent='Admin · Full user profile';const dialog=$('publicProfileDialog');const content=$('publicProfileContent');content.innerHTML='<div class="loading-row"><span class="button-spinner"></span>Loading full user profile and quiz history…</div>';dialog.showModal();try{const d=await api(`/api/admin/users/${encodeURIComponent(userId)}`);if(generation!==authGeneration||!currentUser?.isAdmin||requestSequence!==publicProfileRequestSequence)return;const u=d.user;const statusTags=`<span class="status-pill ${u.loggedIn?'online':'offline'}">${u.loggedIn?'Logged in':'Not recently online'}</span><span class="status-pill ${u.isActive?'active':'inactive'}">${u.isActive?'Active':'Inactive'}</span><span class="status-pill ${u.emailVerified?'active':'offline'}">${u.emailVerified?'Email verified':'Email not verified'}</span><span class="status-pill ${u.suspended?'offline':'active'}">${u.suspended?'Suspended':'Not suspended'}</span>`;const history=(d.quizHistory||[]).map(a=>`<tr><td>${escapeHtml(a.quizTitle)}<small>${dateFmt(a.quizStartsAt)}</small></td><td>${escapeHtml(a.status)}${a.disqualificationReason?`<small>${escapeHtml(a.disqualificationReason)}</small>`:''}</td><td>${a.score}/${a.totalPoints}<small>${a.percentage}% · ${a.rank?`Rank #${a.rank}`:'No rank'}</small></td><td>${Math.floor(a.elapsedSeconds/60)}m ${a.elapsedSeconds%60}s<small>${a.copyWarnings} copy warning(s) · ${Number(a.fullscreenViolations||0)} fullscreen/focus warning(s)</small></td><td>${a.prizeAwarded?`₹${Number(a.prizeAmount).toLocaleString('en-IN')} selected`:'No prize'}<small>${a.prizeReceived?`User-confirmed receipt: ₹${Number(a.prizeReceiptConfirmedAmount).toLocaleString('en-IN')}`:'Receipt not confirmed by user'}</small></td></tr>`).join('');const friends=(u.friends||[]).map(f=>`<li><b>${escapeHtml(f.displayName)}</b> @${escapeHtml(f.username)} <span class="muted">· Last active ${f.lastActiveAt?dateFmt(f.lastActiveAt):'Never'}</span></li>`).join('');const blockedUsers=(u.blockedUsers||[]).map(b=>`<li><b>${escapeHtml(b.displayName)}</b> @${escapeHtml(b.username)}</li>`).join('');content.innerHTML=`<div class="profile-cover">${avatar(u)}<div><h3>${escapeHtml(u.displayName)}</h3><p>@${escapeHtml(u.username)} · ${escapeHtml(u.role)}</p>${statusTags}</div></div><section class="admin-private-data"><h4>Contact and payout (admin only)</h4><p><b>Email:</b> ${u.email?`<a href="mailto:${escapeHtml(u.email)}">${escapeHtml(u.email)}</a>`:'Not available'}</p><p><b>Phone:</b> ${u.phoneNumber?`<a href="tel:${escapeHtml(u.phoneNumber)}">${escapeHtml(u.phoneNumber)}</a>`:'Not provided'}</p><p><b>UPI ID:</b> ${u.upiId?`<code>${escapeHtml(u.upiId)}</code>`:'Not added by user'}</p><p><b>Joined:</b> ${dateFmt(u.createdAt)} · <b>Updated:</b> ${dateFmt(u.updatedAt)} · <b>Last active:</b> ${dateFmt(u.lastActiveAt)||'Never'}</p><p><b>Suspension reason:</b> ${escapeHtml(u.suspensionReason||'—')}</p><h4>Profile and account details</h4><p><b>Bio:</b> ${escapeHtml(u.bio||'—')}</p><p><b>Interests:</b> ${escapeHtml((u.interests||[]).join(', ')||'—')}</p><p><b>Learning goals:</b> ${escapeHtml((u.learningGoals||[]).join(', ')||'—')}</p><p><b>Achievements:</b> ${escapeHtml((u.achievements||[]).join(', ')||'—')}</p><p><b>Friends:</b> ${Number(u.friendsCount||0)} · <b>Blocked users:</b> ${Number(u.blockedUsersCount||0)} · <b>Visibility:</b> ${escapeHtml(u.privacy?.profileVisibility||'public')} · <b>Leaderboard:</b> ${u.privacy?.showOnLeaderboard?'Opted in':'Hidden'}</p><p><b>Quick links:</b> ${(u.quickLinks||[]).map(l=>`<a href="${escapeHtml(l.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(l.label)}</a>`).join(' · ')||'—'}</p><h4>Friends list</h4><ul class="admin-friends-list">${friends||'<li>No current friends.</li>'}</ul><h4>Blocked users (${Number(u.blockedUsersCount||0)})</h4><ul class="admin-friends-list">${blockedUsers||'<li>No blocked users.</li>'}</ul><h4>Quiz attempt history (${(d.quizHistory||[]).length})</h4><div class="table-scroll"><table class="admin-history-table"><thead><tr><th>Quiz</th><th>Status</th><th>Performance</th><th>Time & integrity</th><th>Reward</th></tr></thead><tbody>${history||'<tr><td colspan="5">No quiz attempts yet.</td></tr>'}</tbody></table></div><div class="person-actions"><button class="btn secondary small" type="button" data-revoke-user="${escapeHtml(u.id)}">Revoke all sessions</button><button class="btn ${u.suspended?'secondary':'danger'} small" type="button" data-admin-toggle-suspension="${escapeHtml(u.id)}" data-suspended="${u.suspended?'true':'false'}">${u.suspended?'Unsuspend account':'Suspend account'}</button>${u.email?`<a class="btn secondary small" href="mailto:${escapeHtml(u.email)}">Email user</a>`:''}</div></section>`;}catch(e){if(generation===authGeneration&&currentUser?.isAdmin&&requestSequence===publicProfileRequestSequence)content.innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
async function showAdminParticipantProfile(quizId,attemptId){const generation=authGeneration;const requestSequence=++publicProfileRequestSequence;$('publicProfileDialogTitle').textContent='Admin · Quiz participant profile';const dialog=$('publicProfileDialog');const content=$('publicProfileContent');content.innerHTML='<div class="empty-state">Loading private participant profile…</div>';dialog.showModal();try{const d=await api(`/api/admin/quizzes/${quizId}/attempts/${attemptId}/profile`);if(generation!==authGeneration||!currentUser?.isAdmin||requestSequence!==publicProfileRequestSequence)return;const u=d.profile,a=d.attempt;content.innerHTML=`<div class="profile-cover">${avatar(u)}<div><h3>${escapeHtml(u.displayName)}</h3><p>@${escapeHtml(u.username)} · ${escapeHtml(u.role)}</p></div></div><div class="admin-private-data"><h4>Contact details (admin only)</h4><p><b>Email:</b> ${u.email?`<a href="mailto:${escapeHtml(u.email)}">${escapeHtml(u.email)}</a>`:'Not available'}</p><p><b>Phone:</b> ${u.phoneNumber?`<a href="tel:${escapeHtml(u.phoneNumber)}">${escapeHtml(u.phoneNumber)}</a>`:'Not provided'}</p><p><b>UPI ID:</b> ${u.upiId?`<code>${escapeHtml(u.upiId)}</code>`:'Not added'}</p><p><b>Email verified:</b> ${u.emailVerified?'Yes':'No'} · <b>Suspended:</b> ${u.suspended?'Yes':'No'}</p><p><b>Joined:</b> ${dateFmt(u.createdAt)} · <b>Last active:</b> ${dateFmt(u.lastActiveAt)}</p><h4>Profile data</h4><p><b>Bio:</b> ${escapeHtml(u.bio||'—')}</p><p><b>Interests:</b> ${escapeHtml((u.interests||[]).join(', ')||'—')}</p><p><b>Learning goals:</b> ${escapeHtml((u.learningGoals||[]).join(', ')||'—')}</p><p><b>Achievements:</b> ${escapeHtml((u.achievements||[]).join(', ')||'—')} · <b>Friends:</b> ${Number(u.friendsCount||0)}</p><p><b>Privacy:</b> ${escapeHtml(u.privacy?.profileVisibility||'public')} · Leaderboard visibility: ${u.privacy?.showOnLeaderboard?'On':'Off'}</p><p><b>Quick links:</b> ${(u.quickLinks||[]).map(l=>`<a href="${escapeHtml(l.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(l.label)}</a>`).join(' · ')||'—'}</p><h4>Quiz attempt</h4><p><b>Result:</b> ${a.score}/${a.totalPoints} · <b>Time:</b> ${Math.floor(a.elapsedSeconds/60)}m ${a.elapsedSeconds%60}s · <b>Status:</b> ${escapeHtml(a.status)}</p><p><b>Prize:</b> ${a.prizeAwarded?`Selected ₹${Number(a.prizeAmount||0).toLocaleString('en-IN')}${a.prizeReceived?' · receipt confirmed by user':''}`:'Not selected'}</p><div class="person-actions"><a class="btn secondary small" href="mailto:${escapeHtml(u.email||'')}?subject=${encodeURIComponent('Study Lock quiz result')}">Contact by email</a>${u.phoneNumber?`<a class="btn secondary small" href="tel:${escapeHtml(u.phoneNumber)}">Call / message</a>`:''}</div></div>`;}catch(e){if(generation===authGeneration&&currentUser?.isAdmin&&requestSequence===publicProfileRequestSequence)content.innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
async function changePrize(quizId,attemptId,currentAwarded,currentAmount){let awarded=true;let amount=Number(currentAmount||0);if(currentAwarded){const action=prompt('This profile is already marked for a cash prize. Enter a new amount to update it, or type REMOVE to revoke it:',String(amount));if(action===null)return;if(action.trim().toUpperCase()==='REMOVE')awarded=false;else{amount=Number(action);if(!Number.isFinite(amount)||amount<=0){toast('Enter a valid positive prize amount.');return;}}}else{const value=prompt('Cash prize amount in INR (₹):','500');if(value===null)return;amount=Number(value);if(!Number.isFinite(amount)||amount<=0){toast('Enter a valid positive prize amount.');return;}}let note='';if(awarded){note=prompt('Optional public note for the winner (visible only after they confirm receipt):','')||'';}await api(`/api/admin/quizzes/${quizId}/attempts/${attemptId}/prize`,{method:'PATCH',body:{awarded,amount,note}});toast(awarded?'Cash prize selection saved. The winner can confirm receipt.':'Cash prize selection revoked.');await showQuizLeaderboard(quizId);await loadQuizzes();await loadAdminQuizzes();}
async function confirmPrize(quizId){if(!confirm('Confirm that you actually received this cash prize? Once confirmed, the prize amount will be shown to everyone on the leaderboard.'))return;try{const d=await api(`/api/quizzes/${quizId}/prize/confirm`,{method:'POST',body:{}});toast(d.message);await loadQuizzes();await showQuizLeaderboard(quizId);}catch(e){toast(e.message);}}

async function loadAdminChallenges(){if(!currentUser?.isAdmin)return;const generation=authGeneration;const requestId=beginViewRequest('adminChallenges');try{const d=await api('/api/admin/challenges');if(generation!==authGeneration||!currentUser?.isAdmin||!isCurrentViewRequest('adminChallenges',requestId))return;$('adminChallengeList').innerHTML=d.challenges.map(c=>`<article class="admin-challenge-row"><div class="person-main"><b>${escapeHtml(c.title)}</b><small>${c.participantCount} participants · ${escapeHtml(c.type)} · ${escapeHtml(c.visibility)}</small><small>By @${escapeHtml(c.creator?.username||'deleted-user')} · Ends ${dateFmt(c.endsAt)}</small></div><div class="person-actions"><button class="btn secondary small" data-edit-admin-challenge="${escapeHtml(c.id)}">Edit</button><button class="btn danger small" data-delete-admin-challenge="${escapeHtml(c.id)}">Delete</button></div></article>`).join('')||'<div class="empty-state">No challenges to manage.</div>';window._adminChallengeCache=d.challenges;}catch(e){if(generation===authGeneration&&currentUser?.isAdmin&&isCurrentViewRequest('adminChallenges',requestId))$('adminChallengeList').innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
$('refreshAdminChallenges').addEventListener('click',loadAdminChallenges);
async function editAdminChallenge(id){const c=(window._adminChallengeCache||[]).find(x=>x.id===id);if(!c)return;const f=$('challengeForm');f.elements.challengeId.value=c.id;f.elements.title.value=c.title;f.elements.description.value=c.description||'';f.elements.type.value=c.type;f.elements.goal.value=c.goal;f.elements.endsAt.value=toLocalInput(c.endsAt);f.elements.visibility.value=c.visibility;$('challengeFormHeading').textContent='Edit challenge';$('challengeMessage').textContent='Editing an existing challenge.';window.scrollTo({top:f.getBoundingClientRect().top+window.scrollY-100,behavior:'smooth'});}

