$('loginForm').addEventListener('submit',async e=>{e.preventDefault();if(authSubmitting)return;authSubmitting=true;const btn=e.currentTarget.querySelector('[type=submit]');setButtonBusy(btn,true,'Signing in…');message('loginMessage','Checking your credentials…');const f=new FormData(e.currentTarget);try{await afterAuth(await api('/api/auth/login',{method:'POST',body:{emailOrUsername:f.get('emailOrUsername'),password:f.get('password')}}));message('loginMessage','',true);}catch(err){message('loginMessage',err.message);}finally{authSubmitting=false;setButtonBusy(btn,false);}});
$('registerForm').addEventListener('submit',async e=>{e.preventDefault();if(authSubmitting)return;authSubmitting=true;const btn=e.currentTarget.querySelector('[type=submit]');setButtonBusy(btn,true,'Creating account…');message('registerMessage','Creating your account…');const f=new FormData(e.currentTarget);try{const result=await api('/api/auth/register',{method:'POST',body:{displayName:f.get('displayName'),username:f.get('username'),email:f.get('email'),phoneNumber:f.get('phoneNumber'),password:f.get('password'),joinLeaderboard:f.get('joinLeaderboard')==='on',acceptTerms:f.get('acceptTerms')==='on'}});if(result.verificationRequired){message('registerMessage',`${result.message} Also check your spam/junk folder. After verifying, return here and sign in.`,true);return;}await afterAuth(result);message('registerMessage','',true);}catch(err){message('registerMessage',err.message);}finally{authSubmitting=false;setButtonBusy(btn,false);}});
